const scene=new Scene3D(viewport,{onSelected:renderInspector,onChanged:reason=>{if(!restoring){scheduleSave();scheduleHistory(reason)}},onPartAdded:p=>initPart(p),onPartRestored:p=>initPart(p),onTransformEnd:()=>{},onPlacementRejected:(part,other)=>placementFeedback(`${part.userData.name} cannot overlap ${other.userData.name}. Position restored.`,true),onPlacementAdjusted:part=>placementFeedback(`${part.userData.name} moved to the nearest free position.`),onTerminalRejected:(terminal,reason)=>placementFeedback(`${terminal.userData.terminal}: ${reason}.`,true),onMode:updateModeUI,onViewLock:updateViewUI,onViewChanged:updateViewUI,onToolPick:handleToolPick,onFrame:dt=>{engine?.step(dt);instrumentTick+=dt;resultTick+=dt;if(instruments&&instrumentTick>1/30){instrumentTick=0;instruments.tick()}if(resultTick>.1){resultTick=0;refreshResultReadout()}}});
