function initPart(p){if(p.userData.type==="button"){const cap=p.children.find(x=>x.userData.clickableButton);if(cap)cap.userData.clickableButton=true}if(["lcd1602","oled"].includes(p.userData.type)){const screen=p.userData.visual.screen;if(screen)screen.userData.clickableDisplay=true;fastRuntime.renderDisplay(p)}}
function updateInteractivePart(p,key,value){if(!p)return;p.userData.params[key]=value;if(p.userData.type==="button"){const cap=p.children.find(x=>x.userData.clickableButton);if(cap)cap.position.y=value ? .17 : .22}if(["lcd1602","oled"].includes(p.userData.type))fastRuntime.renderDisplay(p);if(scene.selected===p)renderInspector(p);refreshResultReadout();scheduleSave();scheduleHistory("interact")}
let heldButton=null;
viewport.addEventListener("pointerdown",e=>{if(e.button!==0||scene.mode!=="select")return;const hits=scene.pick(e),hit=hits.find(h=>h.object.userData.clickableButton)||hits.find(h=>h.object.userData.clickableDisplay)||hits.find(h=>scene.findPartRoot(h.object)?.userData.type==="logic");if(!hit)return;const p=scene.findPartRoot(hit.object);if(!p)return;if(p.userData.type==="button"){heldButton=p;updateInteractivePart(p,"pressed",true)}else if(p.userData.type==="logic")updateInteractivePart(p,"high",!p.userData.params.high);else if(["lcd1602","oled"].includes(p.userData.type)){previewDisplayId=p.userData.id;document.body.classList.remove("right-collapsed");showTab("result");setTimeout(()=>scene.resize(),30);refreshResultReadout()}});
