function renderParts(filter=""){const f=filter.trim().toLowerCase(),list=$("#partsList");list.innerHTML="";PARTS.filter(p=>(activeCategory==="All"||p.category===activeCategory)&&(p.name.toLowerCase().includes(f)||p.desc.toLowerCase().includes(f))).forEach(p=>{const el=document.createElement("div");el.className="part-card";el.draggable=p.type!=="wire";el.innerHTML=`<div class="icon">${p.icon}</div><div><strong>${p.name}</strong><span>${p.desc}</span><em>${p.category}</em></div>`;if(p.type==="wire")el.onclick=()=>scene.setMode("wire");else{el.onclick=()=>{const part=scene.addPart(p.type,new THREE.Vector3(0,0,0));scene.select(part)};el.addEventListener("dragstart",e=>e.dataTransfer.setData("text/x-part",p.type))}list.appendChild(el)})}renderCategories();renderParts();$("#partSearch").oninput=e=>renderParts(e.target.value);
viewport.addEventListener("dragover",e=>{e.preventDefault();e.dataTransfer.dropEffect="copy"});viewport.addEventListener("drop",e=>{e.preventDefault();const type=e.dataTransfer.getData("text/x-part");if(!type)return;const part=scene.addPart(type,scene.screenToGround(e.clientX,e.clientY)),safe=part.position.clone();if(scene.snapEnabled){scene.snapPart(part);if(scene.findCollision(part))part.position.copy(safe)}scene.updateWires();scene.select(part)});

