function updateModeUI(mode){$("#wireBtn").classList.toggle("active",mode==="wire");$("#modeBadge").textContent=mode.toUpperCase();const hint=$("#toolHint");if(mode==="select")hint.classList.add("hidden");else{hint.classList.remove("hidden");hint.textContent=mode==="wire"?"Choose first terminal":mode==="meter"?"Pick multimeter probe A":mode==="scope"?"Pick oscilloscope channel":mode==="logicprobe"?"Pick logic channel":mode}}
function updateViewUI(){const locked=!!scene?.viewLocked,preset=scene?.viewPreset||"3d",button=$("#viewBtn"),lockButton=$("#viewLockBtn"),badge=$("#viewLockBadge");button?.classList.toggle("active",locked);if(button)button.title=locked?"View locked — press Space to unlock":"Camera presets and view lock — press Space to lock";if(lockButton){lockButton.textContent=locked?"▣ Unlock 3D view":"▢ Lock 3D view";lockButton.classList.toggle("active",locked)}badge?.classList.toggle("hidden",!locked);document.querySelectorAll("#viewMenu [data-view]").forEach(item=>{if(item.dataset.view!=="lock")item.classList.toggle("active",item.dataset.view===preset)})}
