function handleToolPick(mode,step,t){const ref=scene.terminalRef(t),hint=$("#toolHint");if(mode==="wire"){hint.textContent=step?"Choose second terminal":"Choose first terminal";return}if(mode==="meter"){instruments.setMeterProbe(ref);if(instruments.meter[1])scene.setMode("select");else hint.textContent="Pick multimeter probe B"}if(mode==="scope"){instruments.addScope(ref);scene.setMode("select")}if(mode==="logicprobe"){instruments.addLogic(ref);scene.setMode("select")}}
$("#wireBtn").onclick=()=>scene.setMode(scene.mode==="wire"?"select":"wire");$("#wireColor").oninput=e=>scene.setWireColor(e.target.value);$("#rotateBtn").onclick=()=>scene.rotateSelected();$("#snapBtn").onclick=()=>{scene.snapEnabled=!scene.snapEnabled;$("#snapBtn").classList.toggle("active",scene.snapEnabled);if(scene.selected&&scene.snapEnabled){const safe=scene.selected.position.clone();scene.snapPart(scene.selected);const collision=scene.findCollision(scene.selected);if(collision){scene.selected.position.copy(safe);placementFeedback(`${scene.selected.userData.name} cannot snap over ${collision.userData.name}.`,true)}scene.updateWires()}scheduleSave();scheduleHistory("snap")};$("#deleteBtn").onclick=()=>scene.removeSelected();

function renderInspector(part,wire){const el=$("#inspector");$("#selectionLabel").textContent=part?part.userData.name:wire?"Wire":"Nothing selected";if(wire){el.className="inspector";el.innerHTML=`<h3>Wire</h3><div class="field"><label>From</label><span>${wire.from.partId}:${wire.from.terminal}</span></div><div class="field"><label>To</label><span>${wire.to.partId}:${wire.to.terminal}</span></div><div class="field"><label>Color</label><input id="selectedWireColor" type="color" value="#${wire.color.toString(16).padStart(6,"0")}"></div>`;$("#selectedWireColor").oninput=e=>{wire.color=parseInt(e.target.value.slice(1),16);wire.mesh.material.color.setHex(wire.color);scheduleSave();scheduleHistory("wirecolor")};return}if(!part){el.className="inspector empty";el.textContent="Select a component or wire.";return}el.className="inspector";const q=part.userData.params;let html=`<h3>${part.userData.name}</h3><div class="field"><label>ID</label><span>${part.userData.id}</span></div>`;const C={resistor:[["resistance","Resistance","number","Ω"]],battery:[["voltage","Voltage","number","V"]],led:[["forwardVoltage","Forward V","number","V"],["color","Color","color",""]],capacitor:[["capacitance","Capacitance","number","F"]],motor:[["resistance","Winding R","number","Ω"]],button:[["pressed","Pressed","checkbox",""]],pot:[["resistance","Total R","number","Ω"],["position","Wiper","range","0…1",0,1,.01]],ldr:[["light","Light","range","0…1",0,1,.01],["minResistance","Bright R","number","Ω"],["maxResistance","Dark R","number","Ω"]],npn:[["beta","Beta","number",""]],pnp:[["beta","Beta","number",""]],mosfet_n:[["threshold","Vgs threshold","number","V"],["onResistance","Rds(on)","number","Ω"]],servo:[["angle","Angle","range","°",0,180,1]],buzzer:[["frequency","Frequency","number","Hz"],["enabled","Audio","checkbox",""]],functiongen:[["wave","Wave","select","",["sine","square","triangle"]],["amplitude","Amplitude","number","V"],["offset","Offset","number","V"],["frequency","Frequency","number","Hz"]],logic:[["high","High","checkbox",""] ,["voltage","Voltage","number","V"]],analogSensor:[["value","Output","range","V",0,5,.01]],dht22:[["temperature","Temperature","number","°C"],["humidity","Humidity","number","%"]],ultrasonic:[["distance","Distance","number","cm"]],lcd1602:[["text","Text","text",""]],oled:[["text","Text","text",""]],arduino:[["logicVoltage","Logic","number","V"]],nano:[["logicVoltage","Logic","number","V"]],mega:[["logicVoltage","Logic","number","V"]],esp32:[["logicVoltage","Logic","number","V"]],pico:[["logicVoltage","Logic","number","V"]]};for(const cfg of C[part.userData.type]||[]){const [key,label,type,unit,a,b,step]=cfg,val=q[key];let input;if(type==="checkbox")input=`<input data-key="${key}" type="checkbox" ${val?"checked":""}>`;else if(type==="select")input=`<select data-key="${key}">${a.map(v=>`<option ${v===val?"selected":""}>${v}</option>`).join("")}</select>`;else input=`<input data-key="${key}" type="${type}" value="${String(val??"").replaceAll('"','&quot;')}" ${type==="range"?`min="${a}" max="${b}" step="${step}"`:""}>`;html+=`<div class="field"><label>${label}</label><div>${input}<span class="unit">${unit}</span></div></div>`}html+=`<div class="field"><label>Position</label><span>${part.position.x.toFixed(2)}, ${part.position.z.toFixed(2)}</span></div>`;el.innerHTML=html;el.querySelectorAll("[data-key]").forEach(inp=>{const apply=()=>{const k=inp.dataset.key;q[k]=inp.type==="checkbox"?inp.checked:inp.type==="number"||inp.type==="range"?Number(inp.value):inp.value;if(["lcd1602","oled"].includes(part.userData.type))fastRuntime.renderDisplay(part);refreshResultReadout();scheduleSave();scheduleHistory("property")};inp.addEventListener(inp.type==="range"?"input":"change",apply)})}

document.querySelectorAll(".tab").forEach(b=>b.onclick=()=>showTab(b.dataset.tab));function showTab(name){document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x.dataset.tab===name));document.querySelectorAll(".tab-page").forEach(x=>x.classList.remove("active"));$(`#tab-${name}`).classList.add("active")}
$("#meterProbeBtn").onclick=()=>{showTab("instruments");instruments.meter=[null,null];instruments.renderLabels();scene.setMode("meter")};$("#scopeProbeBtn").onclick=()=>scene.setMode("scope");$("#logicProbeBtn").onclick=()=>scene.setMode("logicprobe");$("#scopeClearBtn").onclick=()=>instruments.clearScope();$("#logicClearBtn").onclick=()=>instruments.clearLogic();

function findBoard(avrOnly=false){return[...scene.parts.values()].find(p=>avrOnly?["arduino","nano"].includes(p.userData.type):["arduino","nano","mega","esp32","pico"].includes(p.userData.type))}
function setSimStatus(on,text=on?"running":"stopped"){const compiling=!!on&&/compil/i.test(text),running=!!on&&!compiling,e=$("#simStatus"),runButton=$("#runBtn"),stopButton=$("#stopBtn"),demoButton=$("#demoRunBtn");e.innerHTML=`<span class="status-dot"></span>${text}`;e.classList.toggle("on",on);e.classList.toggle("off",!on);for(const button of [runButton,demoButton]){if(!button)continue;button.classList.toggle("is-running",running);button.classList.toggle("is-busy",compiling);button.disabled=compiling;button.setAttribute("aria-pressed",String(running));button.textContent=compiling?"Compiling…":running?"↻ Restart":"▶ Start"}if(demoButton)demoButton.textContent=compiling?"Compiling firmware…":running?"↻ Restart simulation":"▶ Start simulation";if(stopButton){stopButton.disabled=!running;stopButton.classList.toggle("is-ready",running);stopButton.setAttribute("aria-disabled",String(!running))}if(runButton)runButton.title=compiling?"Firmware compilation in progress":running?"Simulation running — click to restart":"Start simulation (Ctrl+Enter)"}
async function compileCurrent(){let board=findBoard(true);if(!board){board=scene.addPart("arduino",new THREE.Vector3(-3,0,0));logLine("[compiler] Added Arduino Uno target.")}setSimStatus(true,"compiling");try{const result=await compileUnoSketch(codeEditor.value,s=>logLine(`[compiler] ${s}`));hexEditor.value=result.hex;logLine(`[compiler] Done. Flash bytes: ${result.flashBytes??"unknown"}; fits target: ${result.fitsTarget??"unknown"}`);scheduleSave();return result.hex}catch(e){logLine(`[compiler error] ${e.message}`);throw e}finally{setSimStatus(false)}}
async function run(){stop(false);try{if(runtimeMode.value==="avr"){let board=findBoard(true);if(!board)board=scene.addPart("arduino",new THREE.Vector3(-3,0,0));let hex=hexEditor.value.trim();if(!hex)hex=await compileCurrent();await avrRunner.start(hex,board.userData.id);setSimStatus(true,"AVR running");logLine("[sim] AVR8js ATmega328P simulation started.")}else{let board=findBoard(false);if(!board)board=scene.addPart("arduino",new THREE.Vector3(-3,0,0));setSimStatus(true,"fast running");logLine(`[sim] Fast Arduino runtime started on ${board.userData.name}.`);fastRuntime.start(codeEditor.value,board.userData.id).then(()=>{if(fastRuntime.running)setSimStatus(false)}).catch(()=>setSimStatus(false))}}catch(e){setSimStatus(false);logLine(`[run error] ${e.message}`)}}
function stop(write=true){fastRuntime.stop();avrRunner.stop();setSimStatus(false);if(write)logLine("[sim] Simulation stopped.")}
$("#runBtn").onclick=run;$("#demoRunBtn").onclick=run;$("#stopBtn").onclick=()=>stop();$("#compileBtn").onclick=async()=>{try{await compileCurrent();runtimeMode.value="avr";updateRuntimeEditor()}catch{}};$("#loadBlinkBtn").onclick=()=>{codeEditor.value=BLINK_EXAMPLE;renderFirmwarePinMap();scheduleSave();scheduleHistory("code")};runtimeMode.onchange=()=>{updateRuntimeEditor();scheduleSave();scheduleHistory("runtime")};function updateRuntimeEditor(){const avr=runtimeMode.value==="avr";hexEditor.classList.toggle("hidden",!avr);codeEditor.classList.toggle("hidden",avr);$("#compileBtn").classList.toggle("hidden",false);$("#runtimeNote").textContent=avr?"AVR8js mode: Intel HEX executes on a simulated ATmega328P. Compile C++ → HEX loads AVR-GCC/WASM (~55 MB cached by the browser on first use).":"Fast Arduino mode: lightweight local C++-like transpiler for rapid circuit experiments, including virtual display/sensor helpers."}codeEditor.oninput=()=>{renderFirmwarePinMap();scheduleSave();scheduleHistory("code")};hexEditor.oninput=()=>{scheduleSave();scheduleHistory("code")};

$("#spiceBtn").onclick=async()=>{const net=engine.generateSpiceNetlist();logLine("[spice] Generated netlist:\n"+net);try{await runSpice(net,log)}catch(e){logLine(`[spice error] ${e.message}`)}};
$("#clearConsoleBtn").onclick=()=>consoleEl.textContent="";$("#toggleConsoleBtn").onclick=()=>{document.body.classList.toggle("console-collapsed");$("#toggleConsoleBtn").textContent=document.body.classList.contains("console-collapsed")?"Expand":"Collapse";setTimeout(()=>scene.resize(),30)};const toggleLeft=()=>{document.body.classList.toggle("left-collapsed");setTimeout(()=>scene.resize(),30)},toggleRight=()=>{document.body.classList.toggle("right-collapsed");setTimeout(()=>scene.resize(),30)};$("#collapseLeft").onclick=toggleLeft;$("#expandLeft").onclick=toggleLeft;$("#collapseRight").onclick=toggleRight;$("#expandRight").onclick=toggleRight;
const compactQuery=matchMedia("(max-width: 820px)");function syncCompactLayout(){document.body.classList.toggle("compact-layout",compactQuery.matches);if(compactQuery.matches&&!document.body.dataset.compactInitialized){document.body.dataset.compactInitialized="true";document.body.classList.add("left-collapsed","right-collapsed")}setTimeout(()=>scene.resize(),30)}compactQuery.addEventListener?.("change",syncCompactLayout);syncCompactLayout();

function firmwarePinAssignments(code){const declarations=[],seen=new Set(),patterns=[/\b(?:const\s+)?(?:int|byte|uint8_t|uint16_t|long)\s+([A-Za-z_]\w*)\s*=\s*(A?\d+)\s*;/g,/^\s*#define\s+([A-Za-z_]\w*)\s+(A?\d+)\b/gm];for(const pattern of patterns){let match;while((match=pattern.exec(code))){const name=match[1],literal=match[2];if(seen.has(name))continue;const escaped=name.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),analogUse=new RegExp(`\\banalogRead\\s*\\(\\s*${escaped}\\b`).test(code),digitalUse=new RegExp(`\\b(?:pinMode|digitalWrite|digitalRead|analogWrite|tone|noTone)\\s*\\(\\s*${escaped}\\b`).test(code)||new RegExp(`\\.attach\\s*\\(\\s*${escaped}\\b`).test(code);if(!analogUse&&!digitalUse)continue;seen.add(name);declarations.push({name,pin:literal.startsWith("A")?literal:`${analogUse?"A":"D"}${literal.replace(/^A/,"")}`})}}return declarations}
function renderFirmwarePinMap(){const map=$("#firmwarePinMap");if(!map)return;const assignments=firmwarePinAssignments(codeEditor.value),board=findBoard(false);map.classList.toggle("hidden",assignments.length===0);if(!assignments.length){map.replaceChildren();return}const header=document.createElement("header"),title=document.createElement("span"),boardName=document.createElement("small");title.textContent="FIRMWARE PINS";boardName.textContent=board?.userData.name||"NO BOARD";header.append(title,boardName);const rows=assignments.map(({name,pin})=>{const row=document.createElement("div"),dot=document.createElement("i"),number=document.createElement("b"),alias=document.createElement("span"),terminal=board?.userData.terminals[pin],status=!terminal||!terminal.userData.usable?"unavailable":scene.terminalConnections(terminal)>0?"connected":"available";row.className=`firmware-pin-row ${status}`;number.textContent=pin;alias.textContent=name;alias.title=name;row.append(dot,number,alias);return row});map.replaceChildren(header,...rows)}
function updateStats(){const e=$("#statsBadge");if(e)e.textContent=`${scene.parts.size} parts · ${scene.wires.length} wires`;renderFirmwarePinMap()}
function snapshot(){return{app:"OpenCircuit3D",version:3,activePreset,scene:scene.serialize(),code:codeEditor.value,hex:hexEditor.value,runtimeMode:runtimeMode.value,instruments:{meter:instruments.meter,scope:instruments.scope,logic:instruments.logic}}}
function scheduleSave(){updateStats();clearTimeout(saveTimer);$("#saveStatus").textContent="saving…";saveTimer=setTimeout(()=>{localStorage.setItem("opencircuit3d-project-v3",JSON.stringify(snapshot()));$("#saveStatus").textContent="saved locally"},220)}
function scheduleHistory(){if(restoring)return;clearTimeout(historyTimer);historyTimer=setTimeout(()=>history.push(snapshot()),260)}
function applySnapshot(d){if(!d)return;restoring=true;stop(false);scene.load(d.scene||{});codeEditor.value=d.code||BLINK_EXAMPLE;hexEditor.value=d.hex||"";runtimeMode.value=d.runtimeMode||"fast";updateRuntimeEditor();instruments.meter=d.instruments?.meter||[null,null];instruments.scope=d.instruments?.scope||[];instruments.logic=d.instruments?.logic||[];instruments.scopeData=instruments.scope.map(()=>[]);instruments.logicData=instruments.logic.map(()=>[]);instruments.renderLabels();$("#snapBtn").classList.toggle("active",scene.snapEnabled);$("#wireColor").value=`#${scene.wireColor.toString(16).padStart(6,"0")}`;activePreset=null;previewDisplayId=null;$("#resultTitle").textContent="Live circuit";$("#resultDescription").textContent="Run the simulation, interact with components in 3D, and inspect the current output here.";$("#resultControls").innerHTML="";$("#fixReport").classList.add("hidden");if(d.activePreset&&PRESETS[d.activePreset])configureResultPanel(d.activePreset);restoring=false;refreshResultReadout();scheduleSave()}
function undo(){const s=history.undo(snapshot());if(s)applySnapshot(s)}function redo(){const s=history.redo(snapshot());if(s)applySnapshot(s)}$("#undoBtn").onclick=undo;$("#redoBtn").onclick=redo;

